def shortestDistance(wordsDict, word1, word2):
    idx1 = idx2 = -1      # Most recent indices
    min_distance = len(wordsDict)
    for i, word in enumerate(wordsDict):
        if word == word1:
            idx1 = i
            if idx2 != -1:
                min_distance = min(min_distance, abs(idx1 - idx2))
        elif word == word2:
            idx2 = i
            if idx1 != -1:
                min_distance = min(min_distance, abs(idx1 - idx2))
    return min_distance
